package com.nexusdrive.metadata.service.impl;import com.nexusdrive.metadata.entity.*;import com.nexusdrive.metadata.repository.*;import com.nexusdrive.metadata.service.DeduplicationService;import java.util.Optional;import org.springframework.stereotype.Service;@Service public class DeduplicationServiceImpl implements DeduplicationService{private final FileMetadataRepository files;private final ChunkRepository chunks;public DeduplicationServiceImpl(FileMetadataRepository f,ChunkRepository c){files=f;chunks=c;}public Optional<FileMetadata> findDuplicate(String h){return h==null?Optional.empty():files.findFirstByContentHashAndStatus(h,FileMetadata.Status.ACTIVE);}public void cloneChunks(FileMetadata s,FileMetadata t){chunks.findByFileIdOrderByChunkIndex(s.getId()).forEach(x->{Chunk c=new Chunk();c.setFile(t);c.setChunkIndex(x.getChunkIndex());c.setStorageKey(x.getStorageKey());c.setStorageNodeId(x.getStorageNodeId());c.setReplicaNodeIds(x.getReplicaNodeIds().clone());c.setChecksum(x.getChecksum());c.setUploaded(true);c.setPlainSize(x.getPlainSize());chunks.save(c);});}}
